from collections import deque

class Solution:
    def canMeasureWater(self, x: int, y: int, target: int) -> bool:
        if target > x + y:
            return False
        seen = {(0, 0)}
        q = deque([(0, 0)])
        while q:
            a, b = q.popleft()
            if a + b == target:
                return True
            for na, nb in (
                (x, b), (a, y), (0, b), (a, 0),
                (min(x, a + b), max(0, a + b - x)),
                (max(0, a + b - y), min(y, a + b)),
            ):
                if (na, nb) not in seen:
                    seen.add((na, nb))
                    q.append((na, nb))
        return False

