class Solution {
public:
    bool canMeasureWater(int x, int y, int target) {
        if (target > x + y) return false;
        queue<pair<int, int>> q;
        vector<vector<char>> seen(x + 1, vector<char>(y + 1));
        q.push({0, 0});
        seen[0][0] = 1;
        auto visit = [&](int a, int b) {
            if (!seen[a][b]) { seen[a][b] = 1; q.push({a, b}); }
        };
        while (!q.empty()) {
            auto [a, b] = q.front(); q.pop();
            if (a + b == target) return true;
            visit(x, b); visit(a, y); visit(0, b); visit(a, 0);
            visit(min(x, a + b), max(0, a + b - x));
            visit(max(0, a + b - y), min(y, a + b));
        }
        return false;
    }
};

