import java.util.*;

class Solution {
    public boolean canMeasureWater(int x, int y, int target) {
        if (target > x + y) return false;
        Deque<int[]> q = new ArrayDeque<>();
        Set<Long> seen = new HashSet<>();
        q.offer(new int[]{0, 0});
        seen.add(0L);
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int a = cur[0], b = cur[1];
            if (a + b == target) return true;
            int[][] moves = {{x, b}, {a, y}, {0, b}, {a, 0},
                             {Math.min(x, a + b), Math.max(0, a + b - x)},
                             {Math.max(0, a + b - y), Math.min(y, a + b)}};
            for (int[] m : moves) {
                long key = (long) m[0] * 2001 + m[1];
                if (seen.add(key)) q.offer(m);
            }
        }
        return false;
    }
}

