var canMeasureWater = function(x, y, target) {
    if (target > x + y) return false;
    const seen = new Set([0]);
    const q = [[0, 0]];
    const visit = (a, b) => {
        const key = a * 2001 + b;
        if (!seen.has(key)) { seen.add(key); q.push([a, b]); }
    };
    while (q.length) {
        const [a, b] = q.shift();
        if (a + b === target) return true;
        visit(x, b); visit(a, y); visit(0, b); visit(a, 0);
        visit(Math.min(x, a + b), Math.max(0, a + b - x));
        visit(Math.max(0, a + b - y), Math.min(y, a + b));
    }
    return false;
};

